#!perl
use Cassandane::Tiny;

sub test_search_sharedpart
    :min_version_3_3 :needs_component_sieve
    :JMAPExtensions
    ($self)
{
    my $jmap = $self->{jmap};

    my $store = $self->{store};
    my $talk = $store->get_client();

    my $body = "--047d7b33dd729737fe04d3bde348\r\n";
    $body .= "Content-Type: text/plain; charset=UTF-8\r\n";
    $body .= "\r\n";
    $body .= "This is the lady plain text part.";
    $body .= "\r\n";
    $body .= "--047d7b33dd729737fe04d3bde348\r\n";
    $body .= "Content-Type: text/html;charset=\"UTF-8\"\r\n";
    $body .= "\r\n";
    $body .= "<html><body><p>This is the lady html part.</p></body></html>";
    $body .= "\r\n";
    $body .= "--047d7b33dd729737fe04d3bde348--\r\n";

    $self->make_message("lady subject",
        mime_type => "multipart/alternative",
        mime_boundary => "047d7b33dd729737fe04d3bde348",
        body => $body
    ) || die;

    $body = "--h8h89737fe04d3bde348\r\n";
    $body .= "Content-Type: text/plain; charset=UTF-8\r\n";
    $body .= "\r\n";
    $body .= "This is the foobar plain text part.";
    $body .= "\r\n";
    $body .= "--h8h89737fe04d3bde348\r\n";
    $body .= "Content-Type: text/html;charset=\"UTF-8\"\r\n";
    $body .= "\r\n";
    $body .= "<html><body><p>This is the lady html part.</p></body></html>";
    $body .= "\r\n";
    $body .= "--h8h89737fe04d3bde348--\r\n";

    $self->make_message("foobar subject",
        mime_type => "multipart/alternative",
        mime_boundary => "h8h89737fe04d3bde348",
        body => $body
    ) || die;


    $self->{instance}->run_command({cyrus => 1}, 'squatter');

    my $using = [
        'https://cyrusimap.org/ns/jmap/performance',
        'https://cyrusimap.org/ns/jmap/mail',
        'https://cyrusimap.org/ns/jmap/debug',
        'urn:ietf:params:jmap:core',
        'urn:ietf:params:jmap:mail',
    ];

    my $res = $jmap->CallMethods([
        ['Email/query', {
            filter => {text => "foobar"},
            findMatchingParts => JSON::true,
        },"R1"],
    ], $using);
    my $emailIds = $res->[0][1]{ids};
    my $partIds = $res->[0][1]{partIds};

    my $fooId = $emailIds->[0];

    $self->assert_num_equals(1, scalar @$emailIds);
    $self->assert_num_equals(1, scalar keys %$partIds);
    $self->assert_num_equals(1, scalar @{$partIds->{$fooId}});
    $self->assert_str_equals("1", $partIds->{$fooId}[0]);

    $res = $jmap->CallMethods([
        ['Email/query', {
            filter => {text => "lady"},
            findMatchingParts => JSON::true,
        }, "R1"],
    ], $using);
    $emailIds = $res->[0][1]{ids};
    $partIds = $res->[0][1]{partIds};

    my ($ladyId) = grep { $_ ne $fooId } @$emailIds;

    $self->assert_num_equals(2, scalar @$emailIds);
    $self->assert_num_equals(2, scalar keys %$partIds);
    $self->assert_num_equals(1, scalar @{$partIds->{$fooId}});
    $self->assert_num_equals(2, scalar @{$partIds->{$ladyId}});
    $self->assert_contains("2", $partIds->{$fooId});
    $self->assert_contains("1", $partIds->{$ladyId});
    $self->assert_contains("2", $partIds->{$ladyId});
}

#!perl
use Cassandane::Tiny;

sub test_email_query_no_guidsearch_ignore_jmapuploads
    :min_version_3_7 :JMAPExtensions
    ($self)
{
    my $jmap = $self->{jmap};
    my $imap = $self->{store}->get_client();
    my $store = $self->{store};

    my $using = [
        'urn:ietf:params:jmap:core',
        'urn:ietf:params:jmap:mail',
        'urn:ietf:params:jmap:submission',
        'https://cyrusimap.org/ns/jmap/mail',
        'https://cyrusimap.org/ns/jmap/debug',
        'https://cyrusimap.org/ns/jmap/performance',
    ];

    xlog $self, "Create Trash mailbox";
    $imap->create("Trash", "(USE (\\Trash))") || die;

    my $res = $jmap->CallMethods([
        ['Mailbox/query', {
            sort => [{
                property => 'name',
            }],
        }, 'R1'],
        ['Mailbox/get', {
            '#ids' => {
                resultOf => 'R1',
                name => 'Mailbox/query',
                path => '/ids',
            },
            properties => ['name'],
        }, 'R2'],
    ], $using);
    $self->assert_num_equals(2, scalar @{$res->[0][1]{ids}});

    my $inboxId = $res->[0][1]{ids}[0];
    my $trashId = $res->[0][1]{ids}[1];

    xlog $self, "Create message in Inbox";
    $self->make_message('wantThisOne', body => 'blu blu');
    $self->{instance}->run_command({cyrus => 1}, 'squatter');
    $res = $jmap->CallMethods([
        ['Email/query', { }, 'R1'],
    ], $using);
    my $wantEmailId = $res->[0][1]{ids}[0];
    $self->assert_not_null($wantEmailId);

    xlog $self, "Create message that exists both in Trash and #jmap";
    my $admin = $self->{adminstore}->get_client();
    $jmap->Upload('someblob', "text/plain");
    $store->set_folder('Trash');
    $self->make_message('dontWantThisOne', body => 'blu blu');
    $admin->select('user.cassandane.Trash');
    $admin->copy('1', 'user.cassandane.#jmap');
    $self->{instance}->run_command({cyrus => 1}, 'squatter');

    xlog $self, "Query emails exluding Trash";
    $res = $jmap->CallMethods([
        ['Email/query', {
            filter => {
                operator => 'AND',
                conditions => [{
                    text => 'blu',
                }, {
                    inMailboxOtherThan => [$trashId],
                }],
            },
            sort => [
               {
                  "isAscending" => JSON::false,
                  "property" => "receivedAt"
               }
            ],
            disableGuidSearch => JSON::true,
        }, 'R1'],
    ], $using);

    xlog $self, "Assert that message from #jmap folder is not found";
    $self->assert_deep_equals([$wantEmailId], $res->[0][1]{ids});

}

#!perl
use Cassandane::Tiny;

sub test_email_query_guidsearch_scanmode
    :min_version_3_1 :needs_component_sieve
    :JMAPExtensions :SearchSetForceScanMode
    ($self)
{
    my $jmap = $self->{jmap};

    for (my $i = 0; $i < 10; $i++) {
        $self->make_message("msg$i", to => Cassandane::Address->new(
            localpart => "recipient$i",
            domain => 'example.com'
        )) || die;
    }

    xlog $self, "run squatter";
    $self->{instance}->run_command({cyrus => 1}, 'squatter');

    my $using = [
        'urn:ietf:params:jmap:core',
        'urn:ietf:params:jmap:mail',
        'urn:ietf:params:jmap:submission',
        'https://cyrusimap.org/ns/jmap/mail',
        'https://cyrusimap.org/ns/jmap/quota',
        'https://cyrusimap.org/ns/jmap/debug',
        'https://cyrusimap.org/ns/jmap/performance',
    ];

    xlog "Running query with guidsearch";
    my $res = $jmap->CallMethods([
        ['Email/query', {
            filter => {
                to => '@example.com',
            },
        }, 'R1']
    ], $using);
    $self->assert_equals(JSON::true, $res->[0][1]{performance}{details}{isGuidSearch});
    my $guidSearchIds = $res->[0][1]{ids};
    $self->assert_num_equals(10, scalar @{$guidSearchIds});

    xlog "Running query without guidsearch";
    $res = $jmap->CallMethods([
        ['Email/query', {
            filter => {
                to => '@example.com',
            },
            disableGuidSearch => JSON::true,
        }, 'R1']
    ], $using);
    $self->assert_equals(JSON::false, $res->[0][1]{performance}{details}{isGuidSearch});
    my $uidSearchIds = $res->[0][1]{ids};
    $self->assert_num_equals(10, scalar @{$uidSearchIds});

    xlog "Comparing results";
    $self->assert_deep_equals($guidSearchIds, $uidSearchIds);
}

